def _apply_streamlit_secrets() -> None:
    """Copy Streamlit Cloud secrets into env so get_provider() keeps working.

    Local runs have no secrets.toml — Streamlit raises on access, so ignore
    and keep using .env.
    """
    try:
        secrets = st.secrets
        for key in (
            "LLM_PROVIDER",
            "XAI_API_KEY",
            "XAI_MODEL",
            "XAI_BASE_URL",
            "SERPER_API_KEY",
        ):
            val = secrets.get(key)
            if val and not os.getenv(key):
                os.environ[key] = str(val)
    except Exception:
        return

_PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent.parent
_HISTORY_PATH = _PROJECT_ROOT / "results" / "ui_history" / "history.json"
_HISTORY_MAX = 50
_HISTORY_MAX_CLOUD = 15
_HISTORY_LS_KEY = "worthapply_history_v1"


def _on_streamlit_cloud() -> bool:
    return Path("/mount/src").exists()


def _history_cap() -> int:
    return _HISTORY_MAX_CLOUD if _on_streamlit_cloud() else _HISTORY_MAX

